import{_ as i,o as t,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-06-16","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-06-16","date":"2021-06-16T00:00:00.000Z","updated":"2021-06-17T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-16.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-16.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Crimson_SeaStore_2021-06-16.md"};function n(s,l,p,a,u,g){return t(),e("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ol><li><p><strong>设备管理支持</strong>：</p><ul><li>讨论了为支持设备管理而定义zone space和其他结构的需求。</li><li>参考了FTL库和SPDK中的定义，以获取灵感。</li></ul></li><li><p><strong>PR审查与更新</strong>：</p><ul><li>审查并更新了一个成熟的PR，涉及管理多个zones的支持。</li><li>修复了单元测试中的bug，并移除了catch extent。</li></ul></li><li><p><strong>单元测试问题</strong>：</p><ul><li>发现单元测试存在问题，但系统API测试未报告此问题。</li><li>讨论了使用计数器等于1的问题，并计划后续处理。</li></ul></li><li><p><strong>构建问题</strong>：</p><ul><li>在release build中发现parent pointer问题，而debug build未触发此问题。</li><li>讨论了垃圾收集行为，并建议使用mbd测试工具。</li></ul></li><li><p><strong>Ceph Master分支问题</strong>：</p><ul><li>在当前master分支中，创建pool时出现问题，但在旧分支中可以正常工作。</li><li>建议其他人验证是否存在问题。</li></ul></li><li><p><strong>接口要求</strong>：</p><ul><li>讨论了zone设备的接口要求，并建议参考c-store中的segment manager.h。</li><li>需要创建适配器以暴露设备信息。</li></ul></li><li><p><strong>fmt库更新</strong>：</p><ul><li>提议将fmt库从6升级到7.1.3或7.1.4，以解决gcc编译问题。</li><li>创建了格式化构造，希望尽快合并。</li></ul></li><li><p><strong>事务管理器转换</strong>：</p><ul><li>正在进行事务管理器的interrupted future转换。</li><li>计划将所有消费者也转换为使用interrupted future。</li></ul></li><li><p><strong>调试与测试</strong>：</p><ul><li>讨论了在调试过程中遇到的问题，如invalid extent和osd map读取问题。</li><li>建议增加更多调试输出，以帮助定位问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>设备管理支持</strong>：</p><ul><li>定义zone space和其他结构以支持设备管理。</li><li>参考FTL库和SPDK中的定义，以获取灵感。</li></ul></li><li><p><strong>PR审查与更新</strong>：</p><ul><li>更新PR，修复单元测试中的bug，并移除catch extent。</li></ul></li><li><p><strong>构建问题</strong>：</p><ul><li>在release build中发现parent pointer问题，建议使用mbd测试工具。</li></ul></li><li><p><strong>Ceph Master分支问题</strong>：</p><ul><li>建议其他人验证是否存在问题。</li></ul></li><li><p><strong>接口要求</strong>：</p><ul><li>需要创建适配器以暴露设备信息。</li></ul></li><li><p><strong>fmt库更新</strong>：</p><ul><li>将fmt库从6升级到7.1.3或7.1.4。</li></ul></li><li><p><strong>事务管理器转换</strong>：</p><ul><li>正在进行事务管理器的interrupted future转换。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>设备管理支持</strong>：</p><ul><li>定义zone space和其他结构。</li><li>创建适配器以暴露设备信息。</li></ul></li><li><p><strong>PR审查与更新</strong>：</p><ul><li>继续审查和更新PR。</li></ul></li><li><p><strong>构建问题</strong>：</p><ul><li>使用mbd测试工具调试parent pointer问题。</li></ul></li><li><p><strong>Ceph Master分支问题</strong>：</p><ul><li>验证是否存在问题。</li></ul></li><li><p><strong>接口要求</strong>：</p><ul><li>创建适配器以暴露设备信息。</li></ul></li><li><p><strong>fmt库更新</strong>：</p><ul><li>将fmt库从6升级到7.1.3或7.1.4。</li></ul></li><li><p><strong>事务管理器转换</strong>：</p><ul><li>完成事务管理器的interrupted future转换。</li><li>将所有消费者也转换为使用interrupted future。</li></ul></li><li><p><strong>调试与测试</strong>：</p><ul><li>增加更多调试输出，以帮助定位问题。</li><li>验证osd map读取问题。</li></ul></li></ol><p>通过本次会议，团队明确了设备管理支持、PR审查与更新、构建问题、Ceph Master分支问题、接口要求、fmt库更新、事务管理器转换以及调试与测试等方面的关键细节、决定事项和后续行动计划。</p>',8)])])}const m=i(o,[["render",n]]);export{h as __pageData,m as default};
